#include <bits/stdc++.h>
using namespace std;
int main(){
    int n; scanf("%d",&n);
    map<long long,int> id; vector<vector<pair<long long,int>>> g; vector<vector<long long>> P;
    for(int i=1;i<=n;i++){ long long c,s; scanf("%lld %lld",&c,&s);
        if(!id.count(c)){ id[c]=g.size(); g.push_back({}); }
        g[id[c]].push_back({s,i}); }
    int G=g.size(); P.resize(G);
    for(int a=0;a<G;a++){ sort(g[a].rbegin(),g[a].rend()); P[a].assign(g[a].size()+1,0);
        for(size_t j=0;j<g[a].size();j++) P[a][j+1]=P[a][j]+g[a][j].first; }
    set<int> ks; for(int a=0;a<G;a++) ks.insert(g[a].size());
    long long best=-1; int BA=-1,BB=-1,KA=0,KB=0;
    for(int k:ks){
        long long v[2]={-1,-1}; int ib[2]={-1,-1};
        for(int b=0;b<G;b++){ int cb=g[b].size(); if(cb<k) continue;
            long long val=P[b][min(cb,k+1)];
            if(val>v[0]){ v[1]=v[0]; ib[1]=ib[0]; v[0]=val; ib[0]=b; } else if(val>v[1]){ v[1]=val; ib[1]=b; } }
        for(int a=0;a<G;a++){ if((int)g[a].size()!=k) continue;
            int b=ib[ib[0]!=a?0:1]; if(b<0) continue;
            int kb=min((int)g[b].size(),k+1); long long val=P[a][k]+P[b][kb];
            if(val>best){ best=val; BA=a; BB=b; KA=k; KB=kb; } }
    }
    int bot=(KB>KA)?BB:BA, top=(bot==BA)?BB:BA, cbot=(bot==BA)?KA:KB, ctop=(bot==BA)?KB:KA;
    vector<int> seq;
    for(int i=0;i<max(cbot,ctop);i++){ if(i<cbot) seq.push_back(g[bot][i].second); if(i<ctop) seq.push_back(g[top][i].second); }
    printf("%lld\n%d\n",best,(int)seq.size());
    for(int x:seq) printf("%d ",x);
    printf("\n");
}

