    for(int i=0;i<n;i++) cnt[buf[i]-'A']++;
    int v=cnt['A'-'A']+cnt['E'-'A']+cnt['I'-'A']+cnt['O'-'A']+cnt['U'-'A'];
    int y=cnt['Y'-'A'], nn=cnt['N'-'A'], g=cnt['G'-'A'];
    int other=n-v-y-nn-g, best=0;
    for(int yv=0;yv<=y;yv++)
        for(int k=0;k<=min(nn,g);k++){
            int V=v+yv, K=k, S=other+(nn-k)+(g-k)+(y-yv);
            int s=min(V,(K+S)/2);
            int t=min(K,2*s);
            best=max(best,3*s+t);
        }
    printf("%d\n",best);
}

