#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main(){
    int t; if(scanf("%d",&t)!=1) return 0;
    while(t--){
        int n; ll m,k; if(scanf("%d %lld %lld",&n,&m,&k)!=3) return 0;
        vector<ll> L(n),R(n),B={1}; vector<ll> pre(n+1,0);
        for(int i=0;i<n;i++){
            if(scanf("%lld %lld",&L[i],&R[i])!=2) return 0;
            pre[i+1]=pre[i]+R[i]-L[i]+1;
            for(ll c: {L[i]+1, R[i]+2, L[i]-m+1, R[i]+2-m}) if(c>=1) B.push_back(c);
        }
        sort(B.begin(),B.end()); B.erase(unique(B.begin(),B.end()),B.end());
        auto P=[&](ll x)->ll{
            if(x<=0) return 0;
            int i=upper_bound(L.begin(),L.end(),x)-L.begin();
            if(i==0) return 0;
            return pre[i-1]+min(R[i-1],x)-L[i-1]+1;
        };
        auto F=[&](ll s){ return P(s+m-1)-P(s-1); };
        ll ans=-1;
        for(size_t j=0;j<B.size() && ans<0;j++){
            ll a=B[j], b=(j+1<B.size())?B[j+1]-1:a;
            ll fa=F(a), fb=F(b);
            if(fa==k){ ans=a; break; }
            if(fb==k){ ans=b; break; }
            if(fa==fb) continue;
            ll lo=a, hi=b;
            while(lo<hi){
                ll mid=lo+(hi-lo)/2;
                bool less = (fa<fb) ? (F(mid)<k) : (F(mid)>k);
                if(less) lo=mid+1; else hi=mid;
            }
            if(F(lo)==k) ans=lo;
        }
        printf("%lld\n",ans);
    }
}

