int main(){
    int n,x; scanf("%d %d",&n,&x);
    vector<ll> a(n); for(auto&v:a) scanf("%lld",&v);
    int x0=x-1; const ll INF=LLONG_MAX/4;
    vector<ll> pm(n,INF);
    for(int L=1;L<=n-1;L++) pm[L]=min(L>1?pm[L-1]:INF, a[(x0+L)%n]);
    ll minA=INF; int s0=-1, r=-1; ll q=-1;
    for(int rr=1;rr<=n-1 && s0<0;rr++){
        minA=min(minA, a[((x0-rr+1)%n+n)%n]-1);
        int S=((x0-rr)%n+n)%n; int L=n-rr-1; ll qq=a[S];
        if(minA>=qq && (L==0 || pm[L]>=qq)){ s0=S; r=rr; q=qq; }
    }
    if(s0<0 && a[x0]>=1 && pm[n-1]-1>=a[x0]-1){ s0=x0; r=n; q=a[x0]-1; }
    if(s0<0){ puts("-1"); return 0; }
    vector<ll> b(n);
    for(int j=0;j<n;j++){
        if(j==s0){ b[j]=q*n+r; continue; }
        int d=((j-s0)%n+n)%n;
        b[j]=a[j]-q-((d>=1 && d<=r)?1:0);
    }
    for(int j=0;j<n;j++) printf("%lld ",b[j]);
