    vector<int> w(n); for(auto&v:w) scanf("%d",&v);
    set<pair<int,int>> lab; vector<pair<int,int>> ans;
    for(int i=0;i<n;i++){
        auto it=diag.find(w[i]);
        if(it==diag.end() || it->second.empty()){ puts("NO"); return 0; }
        int x=*it->second.begin(), y=x+w[i];
        if(x>0 && S.count({x-1,y}) && !lab.count({x-1,y})){ puts("NO"); return 0; }
        if(y>0 && S.count({x,y-1}) && !lab.count({x,y-1})){ puts("NO"); return 0; }
        it->second.erase(it->second.begin());
        lab.insert({x,y}); ans.push_back({x,y});
    }
    puts("YES");
    for(auto&p:ans) printf("%d %d\n",p.first,p.second);
}
